public <IT> Pair<OperatorID, OutputFormat<IT>> getUniqueOutputFormat() {
    Map<OperatorID, UserCodeWrapper<? extends OutputFormat<?>>> outputFormats = formats.getOutputFormats();
    Preconditions.checkState(outputFormats.size() == 1);
