            // Intended call: Token<AuthenticationTokenIdentifier> token
            // =
            // TokenUtil.obtainToken(conf);
            token = ((Token<?>) (Class.forName("org.apache.hadoop.hbase.security.token.TokenUtil").getMethod("obtainToken", Configuration.class).invoke(null, hbaseConf)));
        } catch (NoSuchMethodException e) {
            // for HBase 2
            // ----
            // Intended call: ConnectionFactory connectionFactory =
            // ConnectionFactory.createConnection(conf);
            Closeable connectionFactory = ((Closeable) (Class.forName("org.apache.hadoop.hbase.client.ConnectionFactory").getMethod("createConnection", Configuration.class).invoke(null, hbaseConf)));
            // ----
            Class<?> connectionClass = Class.forName("org.apache.hadoop.hbase.client.Connection");
            // ----
            // Intended call: Token<AuthenticationTokenIdentifier> token
            // =
            // TokenUtil.obtainToken(connectionFactory);
            token = ((Token<?>) (Class.forName("org.apache.hadoop.hbase.security.token.TokenUtil").getMethod("obtainToken", connectionClass).invoke(null, connectionFactory)));
