public static long getIssueDate(Clock clock, String tokenKind, AbstractDelegationTokenIdentifier identifier) {
    long now = clock.millis();
    // PATH: Test should invoke the next AbstractDelegationTokenIdentifier.getIssueDate(...) [step in execution path]
    long issueDate = identifier.getIssueDate();
    if (issueDate > now) {
        LOG.warn((("Token {} has set up issue date later than current time. (provided: " + "{} / current timestamp: {}) Please make sure clocks are in sync between ") + "machines. If the issue is not a clock mismatch, consult token implementor to check ") + "whether issue date is valid.", tokenKind, issueDate, now);
        return issueDate;
    } else if (issueDate > 0) {
        return issueDate;
    } else {
        LOG.warn(("Token {} has not set up issue date properly. (provided: {}) " + "Using current timestamp ({}) as issue date instead. Consult token implementor to fix ") + "the behavior.", tokenKind, issueDate, now);
        return now;
    }
}

