public static String createChainedName(Integer vertexID, List<StreamEdge> chainedOutputs, Optional<OperatorChainInfo> operatorChainInfo, Map<Integer, String> chainedNames, JobVertexBuildContext jobVertexBuildContext) {
    StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
    List<ChainedSourceInfo> chainedSourceInfos = operatorChainInfo.map(chainInfo -> getChainedSourcesByVertexId(vertexID, chainInfo, streamGraph)).orElse(Collections.emptyList());
    final String operatorName = nameWithChainedSourcesInfo(streamGraph.getStreamNode(vertexID).getOperatorName(), chainedSourceInfos);
    if (chainedOutputs.size() > 1) {
        List<String> outputChainedNames = new ArrayList<>();
        for (StreamEdge chainable : chainedOutputs) {
            outputChainedNames.add(chainedNames.get(chainable.getTargetId()));
        }
        // PATH: Test should invoke the next StringUtils.join(...) [step in execution path]
        return ((operatorName + " -> (") + StringUtils.join(outputChainedNames, ", ")) + ")";
    } else if (chainedOutputs.size() == 1) {
        return (operatorName + " -> ") + chainedNames.get(chainedOutputs.get(0).getTargetId());
    } else {
        return operatorName;
    }
}

