private StreamingJobGraphGenerator(ClassLoader userClassloader, StreamGraph streamGraph, @Nullable
JobID jobID, Executor serializationExecutor) {
    this.userClassloader = userClassloader;
    this.streamGraph = streamGraph;
    this.defaultStreamGraphHasher = new StreamGraphHasherV2();
    this.legacyStreamGraphHashers = Arrays.asList(new StreamGraphUserHashHasher());
    this.serializationExecutor = Preconditions.checkNotNull(serializationExecutor);
    jobGraph = createAndInitializeJobGraph(streamGraph, jobID);
    // Generate deterministic hashes for the nodes in order to identify them across
    // submission iff they didn't change.
    final Map<Integer, byte[]> hashes = defaultStreamGraphHasher.traverseStreamGraphAndGenerateHashes(streamGraph);
    // Generate legacy version hashes for backwards compatibility
    final List<Map<Integer, byte[]>> legacyHashes = new ArrayList<>(legacyStreamGraphHashers.size());
    for (StreamGraphHasher hasher : legacyStreamGraphHashers) {
        legacyHashes.add(hasher.traverseStreamGraphAndGenerateHashes(streamGraph));
    }
    this.jobVertexBuildContext = new JobVertexBuildContext(jobGraph, streamGraph, new AtomicBoolean(false), hashes, legacyHashes, new SlotSharingGroup());
}

