private static void checkAndReplaceReusableHybridPartitionType(NonChainedOutput reusableOutput) {
    if (reusableOutput.getPartitionType() == ResultPartitionType.HYBRID_SELECTIVE) {
        // for can be reused hybrid output, it can be optimized to always use full
        // spilling strategy to significantly reduce shuffle data writing cost.
        reusableOutput.setPartitionType(ResultPartitionType.HYBRID_FULL);
        LOG.info("{} result partition has been replaced by {} result partition to support partition reuse," + " which will reduce shuffle data writing cost.", reusableOutput.getPartitionType().name(), ResultPartitionType.HYBRID_FULL.name());
    }
}

@SuppressWarnings("deprecation")
public static void preValidate(StreamGraph streamGraph, ClassLoader userClassloader) {
    CheckpointConfig checkpointConfig = streamGraph.getCheckpointConfig();
    if (checkpointConfig.isCheckpointingEnabled()) {
        // temporarily forbid checkpointing for iterative jobs
        if ((streamGraph.isIterative() && checkpointConfig.isUnalignedCheckpointsEnabled()) && (!checkpointConfig.isForceUnalignedCheckpoints())) {
            throw new UnsupportedOperationException(("Unaligned Checkpoints are currently not supported for iterative jobs, " + "as rescaling would require alignment (in addition to the reduced checkpointing guarantees).") + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
        }
        if ((checkpointConfig.isUnalignedCheckpointsEnabled() && (!checkpointConfig.isForceUnalignedCheckpoints())) && streamGraph.getStreamNodes().stream().anyMatch(StreamingJobGraphGenerator::hasCustomPartitioner)) {
            throw new UnsupportedOperationException(("Unaligned checkpoints are currently not supported for custom partitioners, " + "as rescaling is not guaranteed to work correctly.") + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
        }
        for (StreamNode node : streamGraph.getStreamNodes()) {
            StreamOperatorFactory operatorFactory = node.getOperatorFactory();
            if (operatorFactory != null) {
                Class<?> operatorClass = operatorFactory.getStreamOperatorClass(userClassloader);
                if (InputSelectable.class.isAssignableFrom(operatorClass)) {
                    throw new UnsupportedOperationException("Checkpointing is currently not supported for operators that implement InputSelectable:" + operatorClass.getName());
                }
            }
        }
    }
    if (checkpointConfig.isUnalignedCheckpointsEnabled() && (streamGraph.getCheckpointingMode() != CheckpointingMode.EXACTLY_ONCE)) {
        LOG.warn("Unaligned checkpoints can only be used with checkpointing mode EXACTLY_ONCE");
        checkpointConfig.enableUnalignedCheckpoints(false);
    }
}

private void setAllVertexNonChainedOutputsConfigs(final Map<Integer, Map<StreamEdge, NonChainedOutput>> opIntermediateOutputs) {
    jobVertexBuildContext.getJobVerticesInOrder().keySet().forEach(startNodeId -> setVertexNonChainedOutputsConfig(startNodeId, jobVertexBuildContext.getChainInfo(startNodeId).getOperatorInfo(startNodeId).getVertexConfig(), jobVertexBuildContext.getChainInfo(startNodeId).getTransitiveOutEdges(), opIntermediateOutputs));
}

private void setVertexNonChainedOutputsConfig(Integer startNodeId, StreamConfig config, List<StreamEdge> transitiveOutEdges, final Map<Integer, Map<StreamEdge, NonChainedOutput>> opIntermediateOutputs) {
    LinkedHashSet<NonChainedOutput> transitiveOutputs = new LinkedHashSet<>();
    for (StreamEdge edge : transitiveOutEdges) {
        NonChainedOutput output = opIntermediateOutputs.get(edge.getSourceId()).get(edge);
        transitiveOutputs.add(output);
        connect(startNodeId, edge, output, jobVertexBuildContext.getJobVerticesInOrder(), jobVertexBuildContext).increaseNumJobEdgesToCreate();
    }
    config.setVertexNonChainedOutputs(new ArrayList<>(transitiveOutputs));
}

/**
 * This method is used to reset or set job vertices' parallelism for dynamic graph:
 *
 * <p>1. Reset parallelism for job vertices whose parallelism is not configured.
 *
 * <p>2. Set parallelism and maxParallelism for job vertices in forward group, to ensure the
 * parallelism and maxParallelism of vertices in the same forward group to be the same; set the
 * parallelism at early stage if possible, to avoid invalid partition reuse.
 */
private void setVertexParallelismsForDynamicGraphIfNecessary() {
    final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
    // Note that the jobVertices are reverse topological order
    final List<JobVertex> topologicalOrderVertices = IterableUtils.toStream(jobVertices.values()).collect(Collectors.toList());
    Collections.reverse(topologicalOrderVertices);
    // reset parallelism for job vertices whose parallelism is not configured
    jobVertices.forEach((startNodeId, jobVertex) -> {
        final OperatorChainInfo chainInfo = jobVertexBuildContext.getChainInfo(startNodeId);
        if ((!jobVertex.isParallelismConfigured()) && streamGraph.isAutoParallelismEnabled()) {
            jobVertex.setParallelism(ExecutionConfig.PARALLELISM_DEFAULT);
            chainInfo.getAllChainedNodes().forEach(n -> n.setParallelism(ExecutionConfig.PARALLELISM_DEFAULT, false));
        }
    });
    final Map<JobVertex, Set<JobVertex>> forwardProducersByJobVertex = new HashMap<>();
    jobVertices.forEach((startNodeId, jobVertex) -> {
        Set<JobVertex> forwardConsumers = jobVertexBuildContext.getChainInfo(startNodeId).getTransitiveOutEdges().stream().filter(edge -> edge.getPartitioner() instanceof ForwardPartitioner).map(StreamEdge::getTargetId).map(jobVertices::get).collect(Collectors.toSet());
        for (JobVertex forwardConsumer : forwardConsumers) {
            forwardProducersByJobVertex.compute(forwardConsumer, (ignored, producers) -> {
                if (producers == null) {
                    producers = new HashSet<>();
                }
                producers.add(jobVertex);
                return producers;
            });
        }
    });
    // compute forward groups
    final Map<JobVertexID, JobVertexForwardGroup> forwardGroupsByJobVertexId = ForwardGroupComputeUtil.computeForwardGroups(topologicalOrderVertices, jobVertex -> forwardProducersByJobVertex.getOrDefault(jobVertex, Collections.emptySet()));
    jobVertices.forEach((startNodeId, jobVertex) -> {
        ForwardGroup forwardGroup = forwardGroupsByJobVertexId.get(jobVertex.getID());
        // set parallelism for vertices in forward group
        if ((forwardGroup != null) && forwardGroup.isParallelismDecided()) {
            jobVertex.setParallelism(forwardGroup.getParallelism());
            jobVertex.setParallelismConfigured(true);
            jobVertexBuildContext.getChainInfo(startNodeId).getAllChainedNodes().forEach(streamNode -> streamNode.setParallelism(forwardGroup.getParallelism(), true));
        }
        // set max parallelism for vertices in forward group
        if ((forwardGroup != null) && forwardGroup.isMaxParallelismDecided()) {
            jobVertex.setMaxParallelism(forwardGroup.getMaxParallelism());
            jobVertexBuildContext.getChainInfo(startNodeId).getAllChainedNodes().forEach(streamNode -> streamNode.setMaxParallelism(forwardGroup.getMaxParallelism()));
        }
    });
}

