/**
 * Set temporary configuration directories if necessary.
 *
 * @param configuration
 * 		flink config to patch
 * @param defaultDirs
 * 		in case no tmp directories is set, next directories will be applied
 */
public static void updateTmpDirectoriesInConfiguration(Configuration configuration, @Nullable
String defaultDirs) {
    if (configuration.contains(CoreOptions.TMP_DIRS)) {
        LOG.info("Overriding Flink's temporary file directories with those " + "specified in the Flink config: {}", configuration.getValue(CoreOptions.TMP_DIRS));
    } else if (defaultDirs != null) {
        LOG.info("Setting directories for temporary files to: {}", defaultDirs);
        configuration.set(CoreOptions.TMP_DIRS, defaultDirs);
        configuration.set(USE_LOCAL_DEFAULT_TMP_DIRS, true);
    }
}

