@Override
public boolean hasNext() {
    if ((null != offsets) && (offPos < offsets.length)) {
        return true;
    }
    closeCurrentStream();
    while (stateHandleIterator.hasNext()) {
        currentStateHandle = stateHandleIterator.next();
        OperatorStateHandle.StateMetaInfo metaInfo = currentStateHandle.getStateNameToPartitionOffsets().get(stateName);
        if (null != metaInfo) {
            long[] metaOffsets = metaInfo.getOffsets();
            if ((null != metaOffsets) && (metaOffsets.length > 0)) {
                this.offsets = metaOffsets;
                this.offPos = 0;
                if (closableRegistry.unregisterCloseable(currentStream)) // PATH: Test should invoke the next IOUtils.closeQuietly(...) [step in execution path]
                {
                    IOUtils.closeQuietly(currentStream);
                    currentStream = null;
                }
