@Override
public void install() throws SecurityInstallException {
    UserGroupInformation.setConfiguration(hadoopConfiguration);
    UserGroupInformation loginUser;
    try {
        KerberosLoginProvider kerberosLoginProvider = new KerberosLoginProvider(securityConfig);
        if (kerberosLoginProvider.isLoginPossible(true)) {
            kerberosLoginProvider.doLogin(true);
            loginUser = UserGroupInformation.getLoginUser();
            if (HadoopUserUtils.isProxyUser(loginUser) && securityConfig.getFlinkConfig().get(SecurityOptions.DELEGATION_TOKENS_ENABLED)) {
                throw new UnsupportedOperationException(((("Hadoop Proxy user is supported only when" + " delegation tokens fetch is managed outside of Flink!") + " Please try again with ") + SecurityOptions.DELEGATION_TOKENS_ENABLED.key()) + " config set to false!");
            }
            // PATH: Test should invoke the next UserGroupInformation.isFromKeytab(...) [step in execution path]
            if (loginUser.isFromKeytab()) {
                String fileLocation = System.getenv(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION);
                if (fileLocation != null) {
                    Credentials credentials = Credentials.readTokenStorageFile(new File(fileLocation), hadoopConfiguration);
                    loginUser.addCredentials(credentials);
                }
                tgtRenewalExecutorService = Executors.newSingleThreadScheduledExecutor(new ExecutorThreadFactory("TGTRenewalExecutorService"));
                startTGTRenewal(tgtRenewalExecutorService, loginUser);
            }
        } else {
            loginUser = UserGroupInformation.getLoginUser();
        }
        LOG.info("Hadoop user set to {}", loginUser);
        boolean isKerberosSecurityEnabled = HadoopUserUtils.hasUserKerberosAuthMethod(loginUser);
        LOG.info("Kerberos security is {}.", isKerberosSecurityEnabled ? "enabled" : "disabled");
        if (isKerberosSecurityEnabled) {
            LOG.info("Kerberos credentials are {}.", loginUser.hasKerberosCredentials() ? "valid" : "invalid");
        }
    } catch (Throwable ex) {
        throw new SecurityInstallException("Unable to set the Hadoop login user", ex);
    }
}

