public State onAnyExecutionNotFinished(Iterable<ExecutionState> notFinishedExecutionStates) // PATH: Test should invoke the next StopWithSavepointTerminationHandlerImpl.terminateExceptionallyWithGlobalFailover(...) [step in execution path]
{
