/**
 * Creates an input gate and all of its input channels.
 */
public SingleInputGate create(@Nonnull
ShuffleIOOwnerContext owner, int gateIndex, @Nonnull
InputGateDeploymentDescriptor igdd, @Nonnull
PartitionProducerStateProvider partitionProducerStateProvider, @Nonnull
InputChannelMetrics metrics) {
    GateBuffersSpec gateBuffersSpec = createGateBuffersSpec(maxRequiredBuffersPerGate, configuredNetworkBuffersPerChannel, floatingNetworkBuffersPerGate, igdd.getConsumedPartitionType(), igdd.getNumConsumedShuffleDescriptors(), tieredStorageConfiguration != null);
    // PATH: Test should invoke the next SingleInputGateFactory.createBufferPoolFactory(...) [step in execution path]
    SupplierWithException<BufferPool, IOException> bufferPoolFactory = createBufferPoolFactory(networkBufferPool, gateBuffersSpec.getRequiredFloatingBuffers(), gateBuffersSpec.getTotalFloatingBuffers());
    BufferDecompressor bufferDecompressor = null;
    if (igdd.getConsumedPartitionType().supportCompression() && batchShuffleCompressionEnabled) {
        bufferDecompressor = new BufferDecompressor(networkBufferSize, compressionCodec);
    }
    final String owningTaskName = owner.getOwnerName();
    final MetricGroup networkInputGroup = owner.getInputGroup();
    SingleInputGate inputGate = new SingleInputGate(owningTaskName, gateIndex, igdd.getConsumedResultId(), igdd.getConsumedPartitionType(), igdd.getNumConsumedShuffleDescriptors(), partitionProducerStateProvider, bufferPoolFactory, bufferDecompressor, networkBufferPool, networkBufferSize, new ThroughputCalculator(SystemClock.getInstance()), maybeCreateBufferDebloater(owningTaskName, gateIndex, networkInputGroup.addGroup(gateIndex)));
    createInputChannelsAndTieredStorageService(owningTaskName, igdd, inputGate, gateBuffersSpec, metrics);
    return inputGate;
}

@VisibleForTesting
static SupplierWithException<BufferPool, IOException> createBufferPoolFactory(BufferPoolFactory bufferPoolFactory, int minFloatingBuffersPerGate, int maxFloatingBuffersPerGate) {
    // PATH: Test should invoke the next Pair.of(...) [step in execution path]
    Pair<Integer, Integer> pair = Pair.of(minFloatingBuffersPerGate, maxFloatingBuffersPerGate);
    return () -> bufferPoolFactory.createBufferPool(pair.getLeft(), pair.getRight());
}

