public SingleInputGateFactory(@Nonnull
ResourceID taskExecutorResourceId, @Nonnull
NettyShuffleEnvironmentConfiguration networkConfig, @Nonnull
ConnectionManager connectionManager, @Nonnull
ResultPartitionManager partitionManager, @Nonnull
TaskEventPublisher taskEventPublisher, @Nonnull
NetworkBufferPool networkBufferPool, @Nullable
TieredStorageConfiguration tieredStorageConfiguration, @Nullable
TieredStorageNettyServiceImpl tieredStorageNettyService) {
    this.taskExecutorResourceId = taskExecutorResourceId;
    this.partitionRequestInitialBackoff = networkConfig.partitionRequestInitialBackoff();
    this.partitionRequestMaxBackoff = networkConfig.partitionRequestMaxBackoff();
    this.partitionRequestListenerTimeout = networkConfig.getPartitionRequestListenerTimeout();
    this.maxRequiredBuffersPerGate = networkConfig.maxRequiredBuffersPerGate();
    this.configuredNetworkBuffersPerChannel = NettyShuffleUtils.getNetworkBuffersPerInputChannel(networkConfig.networkBuffersPerChannel());
    this.floatingNetworkBuffersPerGate = networkConfig.floatingNetworkBuffersPerGate();
    this.batchShuffleCompressionEnabled = networkConfig.isBatchShuffleCompressionEnabled();
    this.compressionCodec = networkConfig.getCompressionCodec();
    this.networkBufferSize = networkConfig.networkBufferSize();
    this.connectionManager = connectionManager;
    this.partitionManager = partitionManager;
    this.taskEventPublisher = taskEventPublisher;
    this.networkBufferPool = networkBufferPool;
    this.debloatConfiguration = networkConfig.getDebloatConfiguration();
