/**
 * Redirect {@link System#out} and {@link System#err} based on {@link TaskManagerOptions#TASK_MANAGER_SYSTEM_OUT_MODE} related options.
 */
public static void redirectSystemOutAndError(Configuration conf) {
    SystemOutMode systemOutMode = conf.get(TASK_MANAGER_SYSTEM_OUT_MODE);
    switch (systemOutMode) {
        case LOG :
            System.out.print(OUT_TO_LOG_TIPS);
            System.err.print(ERR_TO_LOG_TIPS);
            redirectToCurrentLog(conf.get(TASK_MANAGER_SYSTEM_OUT_LOG_CACHE_SIZE).getBytes(), conf.get(TASK_MANAGER_SYSTEM_OUT_LOG_THREAD_NAME));
            break;
        // PATH: Test should invoke the next SystemOutRedirectionUtils.ignoreSystemOutAndError(...) [step in execution path]
        case IGNORE :
            System.out.print(OUT_IGNORE_TIPS);
            System.err.print(ERR_IGNORE_TIPS);
            ignoreSystemOutAndError();
            break;
        case DEFAULT :
        default :
            break;
    }
}

private static void ignoreSystemOutAndError() {
    System.setOut(new NullPrintStream());
    System.setErr(new NullPrintStream());
}

