public PrioritizedOperatorSubtaskState build() {
    int size = alternativesByPriority.size();
    List<StateObjectCollection<OperatorStateHandle>> managedOperatorAlternatives = new ArrayList<>(size);
    List<StateObjectCollection<KeyedStateHandle>> managedKeyedAlternatives = new ArrayList<>(size);
    List<StateObjectCollection<OperatorStateHandle>> rawOperatorAlternatives = new ArrayList<>(size);
    List<StateObjectCollection<KeyedStateHandle>> rawKeyedAlternatives = new ArrayList<>(size);
    List<StateObjectCollection<InputChannelStateHandle>> inputChannelStateAlternatives = new ArrayList<>(size);
    List<StateObjectCollection<ResultSubpartitionStateHandle>> resultSubpartitionStateAlternatives = new ArrayList<>(size);
    for (OperatorSubtaskState subtaskState : alternativesByPriority) {
        if (subtaskState != null) {
            managedKeyedAlternatives.add(subtaskState.getManagedKeyedState());
            rawKeyedAlternatives.add(subtaskState.getRawKeyedState());
            managedOperatorAlternatives.add(subtaskState.getManagedOperatorState());
            rawOperatorAlternatives.add(subtaskState.getRawOperatorState());
            inputChannelStateAlternatives.add(subtaskState.getInputChannelState());
            resultSubpartitionStateAlternatives.add(subtaskState.getResultSubpartitionState());
        }
    }
    return // PATH: Test should invoke the next PrioritizedOperatorSubtaskState$Builder.resolvePrioritizedAlternatives(...) [step in execution path]
    new PrioritizedOperatorSubtaskState(computePrioritizedAlternatives(jobManagerState.getManagedKeyedState(), managedKeyedAlternatives, KeyedStateHandle::getKeyGroupRange), computePrioritizedAlternatives(jobManagerState.getRawKeyedState(), rawKeyedAlternatives, KeyedStateHandle::getKeyGroupRange), resolvePrioritizedAlternatives(jobManagerState.getManagedOperatorState(), managedOperatorAlternatives, eqStateApprover(OperatorStateHandle::getStateNameToPartitionOffsets)), resolvePrioritizedAlternatives(jobManagerState.getRawOperatorState(), rawOperatorAlternatives, eqStateApprover(OperatorStateHandle::getStateNameToPartitionOffsets)), resolvePrioritizedAlternatives(jobManagerState.getInputChannelState(), inputChannelStateAlternatives, eqStateApprover(InputChannelStateHandle::getInfo)), resolvePrioritizedAlternatives(jobManagerState.getResultSubpartitionState(), resultSubpartitionStateAlternatives, eqStateApprover(ResultSubpartitionStateHandle::getInfo)), restoredCheckpointId);
}

/**
 * This helper method resolves the dependencies between the ground truth of the operator
 * state obtained from the job manager and potential alternatives for recovery, e.g. from a
 * task-local source.
 */
<T extends StateObject> List<StateObjectCollection<T>> resolvePrioritizedAlternatives(StateObjectCollection<T> jobManagerState, List<StateObjectCollection<T>> alternativesByPriority, BiFunction<T, T, Boolean> approveFun) {
    // Nothing to resolve if there are no alternatives, or the ground truth has already no
    // state, or if we can assume that a rescaling happened because we find more than one
    // handle in the JM state
    // (this is more a sanity check).
    if ((((alternativesByPriority == null) || alternativesByPriority.isEmpty()) || (!jobManagerState.hasState())) || (jobManagerState.size() != 1)) {
        return Collections.singletonList(jobManagerState);
    }
    // As we know size is == 1
    T reference = jobManagerState.iterator().next();
    // This will contain the end result, we initialize it with the potential max. size.
    List<StateObjectCollection<T>> approved = new ArrayList<>(1 + alternativesByPriority.size());
    for (StateObjectCollection<T> alternative : alternativesByPriority) {
        // We found an alternative to the JM state if it has state, we have a 1:1
        // relationship, and the approve-function signaled true.
        // PATH: Test should invoke the next BooleanUtils.isTrue(...) [step in execution path]
        if ((((alternative != null) && alternative.hasState()) && (alternative.size() == 1)) && BooleanUtils.isTrue(approveFun.apply(reference, alternative.iterator().next()))) {
            approved.add(alternative);
        }
    }
    // Of course we include the ground truth as last alternative.
    approved.add(jobManagerState);
    return Collections.unmodifiableList(approved);
}

