    // this should be the majority of the cases for small records
    // for large records, this portion of the work is very small in comparison anyways
    // PATH: Test should invoke the next SpillingAdaptiveSpanningRecordDeserializer.readNextRecord(...) [step in execution path]
    final DeserializationResult result = readNextRecord(target);
    if (result.isBufferConsumed()) {
        currentBuffer.recycleBuffer();
        currentBuffer = null;
    }
    return result;
}

private DeserializationResult readNextRecord(T target) throws IOException {
    if (nonSpanningWrapper.hasCompleteLength()) {
        // PATH: Test should invoke the next SpillingAdaptiveSpanningRecordDeserializer.readNonSpanningRecord(...) [step in execution path]
        return readNonSpanningRecord(target);
    } else if (nonSpanningWrapper.hasRemaining()) {
        nonSpanningWrapper.transferTo(spanningWrapper.lengthBuffer);
        return PARTIAL_RECORD;
    } else if (spanningWrapper.hasFullRecord()) {
        target.read(spanningWrapper.getInputView());
        spanningWrapper.transferLeftOverTo(nonSpanningWrapper);
        return nonSpanningWrapper.hasRemaining() ? INTERMEDIATE_RECORD_FROM_BUFFER : LAST_RECORD_FROM_BUFFER;
    } else {
        return PARTIAL_RECORD;
    }
}

private DeserializationResult readNonSpanningRecord(T target) throws IOException {
    // following three calls to nonSpanningWrapper from object oriented design would be better
    // to encapsulate inside nonSpanningWrapper, but then nonSpanningWrapper.readInto equivalent
    // would have to return a tuple of DeserializationResult and recordLen, which would affect
    // performance too much
    int recordLen = nonSpanningWrapper.readInt();
    if (nonSpanningWrapper.canReadRecord(recordLen)) {
        return nonSpanningWrapper.readInto(target);
    } else // PATH: Test should invoke the next SpanningWrapper.transferFrom(...) [step in execution path]
    {
        spanningWrapper.transferFrom(nonSpanningWrapper, recordLen);
        return PARTIAL_RECORD;
    }
}

/**
 * Copies the data and transfers the "ownership" (i.e. clears the passed wrapper).
 */
void transferFrom(NonSpanningWrapper partial, int nextRecordLength) throws IOException // PATH: Test should invoke the next SpanningWrapper.updateLength(...) [step in execution path]
{
    updateLength(nextRecordLength);
    accumulatedRecordBytes = (isAboveSpillingThreshold()) ? spill(partial) : partial.copyContentTo(buffer);
    partial.clear();
}

private void updateLength(int length) throws IOException {
    lengthBuffer.clear();
    recordLength = length;
    if (isAboveSpillingThreshold()) {
        // PATH: Test should invoke the next SpanningWrapper.createSpillingChannel(...) [step in execution path]
        spillingChannel = createSpillingChannel();
    } else {
        ensureBufferCapacity(length);
    }
}

@SuppressWarnings("resource")
private FileChannel createSpillingChannel() throws IOException {
    if (spillFile != null) {
        throw new IllegalStateException("Spilling file already exists.");
    }
    // try to find a unique file name for the spilling channel
    int maxAttempts = 10;
    int initialDirIndex = rnd.nextInt(tempDirs.length);
    for (int attempt = 0; attempt < maxAttempts; attempt++) {
        int dirIndex = (initialDirIndex + attempt) % tempDirs.length;
        String directory = tempDirs[dirIndex];
        File file = new File(directory, randomString(rnd) + ".inputchannel");
        try {
            if (file.createNewFile()) {
                spillFile = new RefCountedFile(file);
                return new RandomAccessFile(file, "rw").getChannel();
            }
        } catch (IOException e) {
            // if there is no tempDir left to try
            if (tempDirs.length <= 1) {
                throw e;
            }
            LOG.warn((("Caught an IOException when creating spill file: " + directory) + ". Attempt ") + attempt, e);
            // PATH: Test should invoke the next ArrayUtils.remove(...) [step in execution path]
            tempDirs = ArrayUtils.remove(tempDirs, dirIndex);
        }
    }
    throw new IOException(("Could not find a unique file channel name in '" + Arrays.toString(tempDirs)) + "' for spilling large records during deserialization.");
}

