public SpillingAdaptiveSpanningRecordDeserializer(String[] tmpDirectories, int thresholdForSpilling, int fileBufferSize) {
    nonSpanningWrapper = new NonSpanningWrapper();
    spanningWrapper = new SpanningWrapper(tmpDirectories, Math.max(thresholdForSpilling, MIN_THRESHOLD_FOR_SPILLING), Math.max(fileBufferSize, MIN_FILE_BUFFER_SIZE));
}

